-- `pg_index`'s half of the same polarity (see
-- `unmodelled_column_is_loud_pg_constraint.sql`): all 21 of its columns, and any
-- invented name, used to bind as a zero-row `text` column.
-- @expect-error: 42703 — an unmodelled name over a complete catalog relation
-- The `WHERE` is load-bearing and the fixture is worthless without it: with rows to
-- project, the executor's own per-row `42703` fires and the plan-time gate is never
-- what refused. Only a **zero-row** read can be refused by the binding gate alone —
-- evaluation never reaching the column — so this is the shape that goes red when
-- `columns_complete` is flipped
-- off, and the populated shape is `unmodelled_column_over_populated_relation.sql`.
-- @no-profile-lock: the refusal is the plan-time binding gate over a `VirtualScan`, which
-- index selection never reaches — a catalog view has no index path on either profile, so
-- the setup's indexes cannot change this verdict.
-- @setup
CREATE TYPE cat_mood AS ENUM ('sad', 'ok', 'happy');
CREATE TABLE cat_parent (
  id INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  code TEXT NOT NULL,
  region VARCHAR(8) NOT NULL,
  CONSTRAINT cat_parent_code_region_uq UNIQUE (code, region)
);
CREATE TABLE cat_child (
  cid INT GENERATED BY DEFAULT AS IDENTITY,
  pid INT REFERENCES cat_parent(id) ON DELETE CASCADE,
  qty INT NOT NULL,
  label TEXT,
  price NUMERIC(10,2),
  m cat_mood,
  CONSTRAINT cat_child_qty_positive CHECK (qty > 0),
  -- Two columns, named out of position order: `conkey` is 18.6's `pull_var_clause`
  -- walk order (`{3,2}`), not the table's column order. Integer operands only —
  -- a text literal would drag in the deparser's recorded `''` vs `''::text`
  -- divergence, which is not this constraint's subject.
  CONSTRAINT cat_child_qty_pid CHECK (qty > 1 AND pid > 0)
);
CREATE INDEX cat_child_pid_idx ON cat_child (pid);
CREATE INDEX cat_child_lower_label_idx ON cat_child (lower(label));
CREATE INDEX cat_child_partial_idx ON cat_child (qty) WHERE qty > 10;
CREATE SEQUENCE cat_plain_seq START 5;

-- @test
SELECT nosuch FROM pg_index WHERE indexrelid = 0
